59	diff --git a/src/explore/multi/chat.ts b/src/explore/multi/chat.ts
60	new file mode 100644
61	index 0000000..2715060
62	--- /dev/null
63	+++ b/src/explore/multi/chat.ts
64	@@ -0,0 +1,287 @@
65	+/* ===== Trò chuyện theo khoảng cách (D-041): nút 💬, bảng tin, phím, đồng hồ danh sách gần =====
66	+   Phần DOM của chat; sổ tin và quy tắc gần ở chatCore.ts, bong bóng trên đầu ở labels.ts (exLabelsSay). index.ts gọi attach / sync / detach / setSelf.
67	+   - body.ex-chat: phiên từng có chatOk (máy chủ biết chat) và đang giữ chỗ / đang xem / vừa mất kết nối; CSS chỉ hiện nút khi body.explore.ex-chat.
68	+   - Danh sách gần: setInterval(nearTickMs) từ attach tới detach, ngoài vòng vẽ; chỉ ghi DOM khi khóa danh sách đổi. Vòng vẽ chỉ gọi setSelf (5 lần/s, không cấp phát).
69	+   - Mỗi tin một nút DOM, không dựng lại cả danh sách; quá historyMax thì gỡ nút cũ nhất. Mọi chữ từ mạng ghi bằng textContent.
70	+   - Trình nghe gắn một lần lúc nạp module trên phần tử cố định (index.html), không gắn / gỡ theo lần mở bảng. */
71	+import { CONFIG } from '../../config';
72	+import { t, onChange as onLang } from '../../i18n';
73	+import { exSanitizeChat } from './protocol';
74	+import { ChLog, chKey, chNear, type ChMsg, type ChPeer } from './chatCore';
75	+import { exRemotes } from './remote';
76	+import { stAvatars } from '../stroll/avatars';
77	+import { exDrivers } from './remoteDrive';
78	+import { exLabelsSay } from './labels';
79	+import type { MultiSession } from './session';
80	+
81	+const M = CONFIG.explore.multi, C = M.chat, NW = M.stroll.slots, ND = M.drive.slots;
82	+const log = new ChLog(C.historyMax, C.ackMs, C.ratePerWin, C.rateWinMs);   // giờ trong sổ là Date.now() (cùng đồng hồ cho hạn hồi âm, hạn mức và giờ HH:MM)
83	+interface Els { btn: HTMLButtonElement; near: HTMLElement; dot: HTMLElement; panel: HTMLElement; status: HTMLElement; list: HTMLElement; form: HTMLFormElement; input: HTMLTextAreaElement; send: HTMLButtonElement }
84	+let el: Els | null = null;
85	+const rows = new Map<number, { row: HTMLElement; st: HTMLElement | null }>();   // khóa tin → nút DOM của tin + dòng trạng thái (chỉ tin mình)
86	+let session: MultiSession | null = null;
87	+let had = false;          // phiên này từng có chatOk (mất kết nối thì chatOk về false nhưng vẫn hiện để thấy trạng thái)
88	+let avail = false;        // body.ex-chat đang bật
89	+let opened = false;       // bảng đang mở
90	+let locked = true;        // khóa gửi (không ai ở gần / đang xem / mất kết nối)
91	+let timer = 0;            // setInterval nearTickMs
92	+let self: { x: number; y: number; z: number } | null = null;   // vị trí mình vừa gửi lên máy chủ (đúng cái máy chủ biết)
93	+let prev: Set<string> = new Set();   // khóa người ở gần lần trước (trễ hai ngưỡng)
94	+let near: ChPeer[] = [];
95	+let nearKey = '';         // khóa + tên danh sách gần đang vẽ ('' = rỗng)
96	+
97	+const ERR = new Set(['fail', 'rate', 'bad']);
98	+const two = (v: number) => (v < 10 ? '0' : '') + v;
99	+const hhmm = (ms: number) => { const d = new Date(ms); return two(d.getHours()) + ':' + two(d.getMinutes()); };
100	+
101	+/* Chữ dòng trạng thái của tin mình */
102	+function stText(m: ChMsg): string {
103	+  switch (m.state) {
104	+    case 'pending': return t('chatSending');
105	+    case 'ok': return '✓';
106	+    case 'alone': return t('chatAlone');
107	+    case 'rate': return t('chatRate');
108	+    case 'bad': return t('chatBad');
109	+    default: return t('chatFail');
110	+  }
111	+}
112	+
113	+/* Ghi lại đúng dòng trạng thái của một tin mình */
114	+function paintState(m: ChMsg): void {
115	+  const r = rows.get(m.key);
116	+  if (!r || !r.st) return;
117	+  r.st.textContent = stText(m);
118	+  r.st.title = m.state === 'ok' ? t('chatSent', { n: m.n }) : '';
119	+  r.st.className = 'ex-chat-st' + (ERR.has(m.state) ? ' err' : '');
120	+}
121	+
122	+/* Thêm một tin vào cuối bảng: dòng đầu (chấm màu slot, tên, giờ), thân chữ, và dòng trạng thái với tin mình. Đang ở gần cuối hoặc tin mình thì cuộn xuống cuối */
123	+function addRow(m: ChMsg): void {
124	+  if (!el) return;
125	+  const L = el.list, stick = m.mine || L.scrollHeight - L.scrollTop - L.clientHeight < 40;
126	+  const slot = m.mine ? (session ? session.mySlot : -1) : m.slot, name = m.mine ? (session ? session.name : '') : m.name;
127	+  const row = document.createElement('div'); row.className = 'ex-chat-msg' + (m.mine ? ' me' : '');
128	+  const head = document.createElement('div'); head.className = 'ex-chat-head';
129	+  const dot = document.createElement('i'); dot.style.background = slot >= 0 ? M.colors[slot % M.colors.length] : 'var(--gold)';
130	+  const nm = document.createElement('b'); nm.dir = 'auto'; nm.textContent = name;
131	+  const tm = document.createElement('span'); tm.textContent = hhmm(m.at);
132	+  head.append(dot, nm, tm);
133	+  const body = document.createElement('div'); body.className = 'ex-chat-body'; body.dir = 'auto'; body.textContent = m.text;
134	+  row.append(head, body);
135	+  let st: HTMLElement | null = null;
136	+  if (m.mine) { st = document.createElement('div'); row.appendChild(st); }
137	+  rows.set(m.key, { row, st });
138	+  L.appendChild(row);
139	+  if (m.mine) paintState(m);
140	+  for (const g of log.trim()) { const r = rows.get(g.key); if (r) { r.row.remove(); rows.delete(g.key); } }
141	+  if (stick) L.scrollTop = L.scrollHeight;
142	+}
143	+
144	+/* Chấm đỏ chưa đọc: chỉ khi bảng đóng */
145	+function paintDot(): void { if (el) el.dot.hidden = opened || log.unread === 0; }
146	+
147	+/* Nút gửi khóa khi khóa gửi hoặc ô rỗng */
148	+function paintSend(): void { if (el) el.send.disabled = locked || el.input.value.trim() === ''; }
149	+
150	+/* Dòng trạng thái + khóa gửi theo pha và danh sách gần */
151	+function paintStatus(): void {
152	+  if (!el) return;
153	+  const ph = session ? session.phase : 'solo';
154	+  let txt: string, lock = true;
155	+  if (ph === 'flying') {
156	+    if (near.length === 0) txt = t('chatNone');
157	+    else { lock = false; txt = near.length === 1 ? t('chatOne', { name: '⁨' + near[0].name + '⁩' }) : t('chatMany', { n: near.length }); }   // tên bọc cô lập hướng chữ
158	+  } else txt = t(ph === 'watching' ? 'chatWatch' : 'chatLost');
159	+  if (el.status.textContent !== txt) el.status.textContent = txt;
160	+  if (lock !== locked) { locked = lock; el.input.disabled = lock; }
161	+  paintSend();
162	+}
163	+
164	+/* Huy hiệu số người ở gần + dòng trạng thái */
165	+function paintNear(): void {
166	+  if (!el) return;
167	+  el.near.hidden = near.length === 0;
168	+  el.near.textContent = near.length ? String(near.length) : '';
169	+  paintStatus();
170	+}
171	+
172	+/* Nút nháy một lần khi có người mới vào tầm (gỡ lớp ở animationend; đang nháy thì chạy lại từ đầu) */
173	+function pulse(): void {
174	+  if (!el) return;
175	+  const b = el.btn;
176	+  if (b.classList.contains('pulse')) { b.classList.remove('pulse'); void b.offsetWidth; }
177	+  b.classList.add('pulse');
178	+}
179	+
180	+/* Người khác cùng phòng có trạng thái (bỏ mình và người chưa có mẫu) */
181	+function peers(s: MultiSession): ChPeer[] {
182	+  const out: ChPeer[] = [];
183	+  for (let i = 0; i < M.slots; i++) {
184	+    if (s.kind === 'fly' && i === s.mySlot) continue;
185	+    const st = exRemotes.slotState(i), nm = exRemotes.name(i);
186	+    if (st && nm !== null) out.push({ k: 'fly', slot: i, name: nm, x: st.pos.x, y: st.pos.y, z: st.pos.z });
187	+  }
188	+  for (let i = 0; i < NW; i++) {
189	+    if (i === stAvatars.self || (s.kind === 'walk' && i === s.mySlot)) continue;
190	+    const st = stAvatars.slotState(i), nm = stAvatars.name(i);
191	+    if (st && nm !== null) out.push({ k: 'walk', slot: i, name: nm, x: st.x, y: st.y, z: st.z });
192	+  }
193	+  for (let i = 0; i < ND; i++) {
194	+    if (s.kind === 'drive' && i === s.mySlot) continue;
195	+    const st = exDrivers.slotState(i), nm = exDrivers.name(i);
196	+    if (st && nm !== null) out.push({ k: 'drive', slot: i, name: nm, x: st.x, y: st.y, z: st.z });
197	+  }
198	+  return out;
199	+}
200	+
201	+/* Đồng hồ nearTickMs: tin chờ quá hạn thành "Chưa gửi được"; tính lại danh sách gần (chỉ khi đang giữ chỗ), ghi DOM khi khóa đổi */
202	+function tick(): void {
203	+  const s = session;
204	+  if (!s || !avail) return;
205	+  for (const m of log.expire(Date.now())) paintState(m);
206	+  if (s.phase !== 'flying') return;
207	+  near = chNear(self, peers(s), prev, C.nearIn, C.radius);
208	+  const key = near.map(p => chKey(p.k, p.slot) + '=' + p.name).join('|');
209	+  if (key === nearKey) return;
210	+  nearKey = key;
211	+  const next = new Set<string>();
212	+  let fresh = false;
213	+  for (const p of near) { const k = chKey(p.k, p.slot); next.add(k); if (!prev.has(k)) fresh = true; }
214	+  prev = next;
215	+  if (fresh) pulse();
216	+  paintNear();
217	+}
218	+
219	+/* Quên danh sách gần (không giữ chỗ / rời phiên) */
220	+function dropNear(): void { self = null; prev = new Set(); near = []; nearKey = ''; paintNear(); }
221	+
222	+/* Gửi chữ trong ô: rỗng sau khi làm sạch thì thôi; quá hạn mức thì hiện tin "gửi nhanh quá" mà không gửi; transport không nhận thì "Chưa gửi được" ngay */
223	+function send(): void {
224	+  if (!el || !session || locked) return;
225	+  const text = exSanitizeChat(el.input.value);
226	+  if (text === null) return;
227	+  const now = Date.now();
228	+  const m = log.canSend(now) ? log.addMine(text, now) : log.addMine(text, now, true);
229	+  if (m.state === 'pending' && !session.sendChat(text, m.id)) m.state = 'fail';
230	+  addRow(m);
231	+  el.input.value = ''; fit(); paintSend();
232	+  el.input.focus();
233	+}
234	+
235	+/* Ô nhập tự cao theo nội dung (CSS max-height giữ ≤ 4 dòng) */
236	+function fit(): void {
237	+  if (!el) return;
238	+  const i = el.input;
239	+  i.style.height = 'auto';
240	+  i.style.height = (i.scrollHeight + 2) + 'px';   // + viền trên dưới (box-sizing border-box)
241	+}
242	+
243	+export const exChat = {
244	+  onActivity: (() => {}) as () => void,   // index.ts gán = () => exMulti.activity(): gõ trong ô chat tính là còn đó
245	+
246	+  /* Gắn phiên mới: móc onChat / onChatAck, bật đồng hồ nearTickMs */
247	+  attach(s: MultiSession): void {
248	+    exChat.detach();
249	+    session = s;
250	+    s.onChat = (c) => {
251	+      if (s !== session) return;
252	+      const text = exSanitizeChat(c.text);   // máy chủ đã làm sạch; làm lại để máy chủ lạ không chèn ký tự điều khiển / bidi
253	+      if (text === null) return;
254	+      addRow(log.addTheirs(c.k, c.slot, c.name, text, Date.now(), opened));
255	+      exLabelsSay(c.k, c.slot, text, performance.now());
256	+      paintDot();
257	+    };
258	+    s.onChatAck = (a) => { if (s !== session) return; const m = log.ack(a.id, a.n, a.why); if (m) paintState(m); };
259	+    timer = window.setInterval(tick, C.nearTickMs);
260	+  },
261	+
262	+  /* Gọi trong s.onChange: hiện / ẩn, dòng trạng thái; mất kết nối thì mọi tin đang chờ thành "Chưa gửi được" */
263	+  sync(s: MultiSession): void {
264	+    if (s !== session) return;
265	+    if (s.chatOk) had = true;
266	+    const on = had && (s.phase === 'flying' || s.phase === 'watching' || (s.phase === 'solo' && s.notice === 'lost'));
267	+    if (on !== avail) { avail = on; document.body.classList.toggle('ex-chat', on); if (!on) exChat.close(); }
268	+    if (s.phase === 'solo') for (const m of log.failAll()) paintState(m);
269	+    if (s.phase !== 'flying') dropNear(); else paintStatus();
270	+  },
271	+
272	+  /* exMulti.end(): dừng đồng hồ, xóa sổ + DOM, đóng bảng, bỏ lớp body */
273	+  detach(): void {
274	+    clearInterval(timer); timer = 0;
275	+    if (session) { session.onChat = () => {}; session.onChatAck = () => {}; }
276	+    session = null; had = false;
277	+    log.clear(); rows.clear();
278	+    if (el) el.list.textContent = '';
279	+    exChat.close();
280	+    avail = false; document.body.classList.remove('ex-chat');
281	+    dropNear(); paintDot();
282	+  },
283	+
284	+  /* Vị trí mình vừa gửi lên máy chủ (index.ts, ≤ sendHz lần/s); không cấp phát */
285	+  setSelf(x: number, y: number, z: number): void {
286	+    if (self) { self.x = x; self.y = y; self.z = z; } else self = { x, y, z };
287	+  },
288	+
289	+  open(): void {
290	+    if (!el || !avail) return;
291	+    if (!opened) { opened = true; el.panel.hidden = false; el.btn.setAttribute('aria-expanded', 'true'); }
292	+    log.read(); paintDot();
293	+    el.list.scrollTop = el.list.scrollHeight;
294	+  },
295	+
296	+  /* Đóng bảng; luôn bỏ focus ô nhập (không thì WASD vẫn bị isField nuốt) */
297	+  close(): void {
298	+    if (!el) return;
299	+    if (document.activeElement === el.input) el.input.blur();
300	+    if (!opened) return;
301	+    opened = false; el.panel.hidden = true; el.btn.setAttribute('aria-expanded', 'false');
302	+    paintDot();
303	+  },
304	+
305	+  get isOpen(): boolean { return opened; },
306	+
307	+  /* Cho test (?test): trạng thái giao diện chat */
308	+  debug(): { available: boolean; open: boolean; near: string[]; unread: number; count: number; status: string; canSend: boolean; self: { x: number; y: number; z: number } | null } {
309	+    return { available: avail, open: opened, near: near.map(p => p.name), unread: log.unread, count: log.list.length, status: el ? el.status.textContent : '', canSend: !locked, self: self ? { ...self } : null };
310	+  }
311	+};
312	+
313	+/* ===== Gắn trình nghe một lần (phần tử cố định trong index.html) ===== */
314	+function bind(): void {
315	+  const $ = <T extends HTMLElement>(id: string) => document.getElementById(id) as T | null;
316	+  const btn = $<HTMLButtonElement>('exChatBtn'), panel = $('exChat'), input = $<HTMLTextAreaElement>('exChatIn'), form = $<HTMLFormElement>('exChatForm');
317	+  if (!btn || !panel || !input || !form) return;
318	+  el = { btn, near: $('exChatNear')!, dot: $('exChatDot')!, panel, status: $('exChatStatus')!, list: $('exChatList')!, form, input, send: $<HTMLButtonElement>('exChatSend')! };
319	+  input.placeholder = t('chatPlaceholder');
320	+  input.disabled = true;
321	+  btn.addEventListener('click', () => {
322	+    if (opened) { exChat.close(); return; }
323	+    exChat.open();
324	+    if (!locked && window.matchMedia?.('(hover: hover)').matches) input.focus();   // máy cảm ứng: không tự bật bàn phím ảo che màn hình
325	+  });
326	+  btn.addEventListener('animationend', () => btn.classList.remove('pulse'));
327	+  form.addEventListener('submit', (e) => { e.preventDefault(); send(); });
328	+  input.addEventListener('input', () => { fit(); paintSend(); });
329	+  input.addEventListener('keydown', (e) => {
330	+    exChat.onActivity();
331	+    if (e.key === 'Escape') { e.stopPropagation(); e.preventDefault(); exChat.close(); return; }   // chỉ đóng bảng: không nổi bọt tới window (explore/index.ts thoát chế độ)
332	+    if (e.key === 'Enter' && !e.shiftKey && !e.isComposing && e.keyCode !== 229) { e.preventDefault(); send(); }   // Shift + Enter xuống dòng; đang gõ bộ gõ (IME) thì không gửi
333	+  });
334	+  /* Enter ngoài ô nhập / nút: mở bảng và đưa focus vào ô */
335	+  window.addEventListener('keydown', (e) => {
