   body.drive #drGas{right:calc(16px + env(safe-area-inset-right,0px));bottom:calc(24px + env(safe-area-inset-bottom,0px));width:min(var(--dr-gas-w,92px),24vw);height:var(--dr-gas-h,124px);}
   body.drive #drBrake{right:calc(26px + min(var(--dr-gas-w,92px),24vw) + env(safe-area-inset-right,0px));bottom:calc(24px + env(safe-area-inset-bottom,0px));width:min(var(--dr-brake-w,76px),19vw);height:var(--dr-brake-h,84px);}
   body.drive #drGas.on{background:rgba(230,189,106,.6);border-color:var(--gold);}
   body.drive #drBrake.on{background:rgba(214,70,60,.6);border-color:#e86a5e;}
   body.drive #drMap{left:calc(8px + env(safe-area-inset-left,0px));top:calc(56px + env(safe-area-inset-top,0px));bottom:auto;}   /* dưới hàng nút ⚙ / Thoát (hai góc trên; ar đổi chỗ hai nút) */
   body.drive #drMapNote{left:calc(8px + env(safe-area-inset-left,0px));top:calc(60px + var(--dr-map-h,128px) + env(safe-area-inset-top,0px));bottom:auto;font-size:10px;max-width:calc(50vw - 24px);}
   body.drive #drSpeed{right:auto;bottom:auto;left:50%;transform:translateX(-50%);top:calc(8px + env(safe-area-inset-top,0px));}
 }
+/* Chat khi lái ô tô / xe máy trên điện thoại ngang: giữa mép trái đụng bản đồ nhỏ (trên trái, 56 → ≈ 186 px) nên nút sang cạnh phải bản đồ, ngang đáy bản đồ.
+   Bản đồ cảm ứng: cạnh dài CONFIG.drive.hud.mapTouch 128 px (dọc), ngang ≈ 87 px theo khung mạng đường + viền 1 px ⇒ mép phải 8 + 89 = 97 px; nút ở 97 + 8 = 105 px. Bảng mở cạnh nút.
+   --dr-map-h đặt trên #drHud nên ở đây luôn là giá trị lùi (như #exMpNotice) */
+@media (hover:none) and (orientation:landscape){
+  body.drive.ex-chat #exChatBtn{left:calc(105px + env(safe-area-inset-left,0px));top:calc(56px + var(--dr-map-h,128px) + 2px - 44px + env(safe-area-inset-top,0px));}
+  body.drive.ex-chat #exChat:not([hidden]){left:calc(157px + env(safe-area-inset-left,0px));width:min(300px,calc(100vw - 171px));}
+}
 /* Xe máy (body.explore.drive.bike, explore/bike/hudBike.ts): dùng nguyên khung #drHud của ô tô (đồng hồ, bản đồ nhỏ, cần gạt + GA + PHANH + vuốt nhìn của drive/touch.ts);
    #drHint của ô tô nhường chỗ cho #bkHint. Nút 🔊 #drSoundBtn dời lên góc trên trái cạnh ⚙ (giữa đáy là mặt đồng hồ góc nhìn thứ nhất; trên cần gạt là chỗ xi nhan).
    Máy tính: cột trái dưới ⚙: 🎥 rồi hàng ◄ ►; còi / về làn dùng phím H / R (nút chỉ ở cảm ứng). Cảm ứng: ◄ ► trên cần gạt, hàng ↺ 🎥 📢 trên GA + PHANH,
    vùng chạm ≥ 44 px, trong vùng an toàn. Chế độ xem (Task 10): ẩn mọi nút điều khiển. #drHud dir="ltr" nên ar không lật */
 #bkHint,#bkStuck,.bk-btn{display:none;}
 body.bike #drHint{display:none !important;}
 body.bike:not(.ex-watching) #drSoundBtn{left:calc(72px + env(safe-area-inset-left,0px));right:auto;top:calc(16px + env(safe-area-inset-top,0px));bottom:auto;transform:none;}
 body.bike #bkHint,body.bike #bkStuck{position:fixed;pointer-events:none;left:50%;transform:translateX(-50%);padding:8px 14px;font-size:12px;color:var(--text);text-align:center;width:max-content;max-width:calc(100vw - 280px);box-sizing:border-box;}   /* 280: chừa ⚙ + 🔊 (trái) và Thoát (phải) */
 body.bike #bkHint.off{opacity:0;transition:opacity .6s;}
 body.bike #bkStuck{top:calc(64px + env(safe-area-inset-top,0px));color:var(--gold);font-size:13px;}
